<?php
namespace App\Models; use App\Enums\PaperStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany,HasOne};
class Paper extends Model { protected $guarded=[]; protected function casts():array{return ['status'=>PaperStatus::class,'keywords'=>'array'];} public function uploader():BelongsTo{return $this->belongsTo(User::class,'uploaded_by');} public function authors():HasMany{return $this->hasMany(PaperAuthor::class)->orderBy('position');} public function sections():HasMany{return $this->hasMany(PaperSection::class);} public function analysis():HasOne{return $this->hasOne(PaperAnalysis::class);} public function references():HasMany{return $this->hasMany(PaperReference::class);} public function aiJobs():HasMany{return $this->hasMany(AiJob::class);} public function reviews():HasMany{return $this->hasMany(Review::class);} public function assignments():HasMany{return $this->hasMany(ReviewerAssignment::class);} }
